magazine-cover.variantCss:
/* --- Magazine Cover：待核查的牛皮纸档案袋封面 --- */
.wemd-magazine-cover[data-variant="cangre-audit"] {
  padding: 2rem 1.25rem 2.5rem;
  background: linear-gradient(#f3ebda, #f7f1e6), #f7f1e6;
  border: 1px solid #e5dac6;
  border-radius: 4px;
}
.wemd-magazine-cover[data-variant="cangre-audit"] .wemd-mc-header {
  padding-bottom: 0.5rem;
}
.wemd-magazine-cover[data-variant="cangre-audit"] .wemd-mc-top-bar {
  display: block;
  height: 3px;
  background: #b03a2e; /* 红头条 */
  margin-bottom: 1rem;
}
.wemd-magazine-cover[data-variant="cangre-audit"] .wemd-mc-title {
  font-family: "Songti SC", "STSong", "SimSun", Georgia, serif;
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.4;
  color: #3e3428;
}
.wemd-magazine-cover[data-variant="cangre-audit"] .wemd-mc-subtitle {
  margin-top: 0.5rem;
  font-size: 0.9rem;
  color: #6b5b4e;
}
.wemd-magazine-cover[data-variant="cangre-audit"] .wemd-mc-divider {
  margin: 1rem 0;
  height: 1px;
  background: #e5dac6;
}
.wemd-magazine-cover[data-variant="cangre-audit"] .wemd-mc-main {
  text-align: center;
}
.wemd-magazine-cover[data-variant="cangre-audit"] .wemd-mc-desc {
  font-size: 0.95rem;
  line-height: 1.7;
  color: #6b5b4e;
}

